SELECT column_name, data_type 
FROM information_schema.columns 
WHERE table_schema = 'payments' AND table_name = 'customer_complaints';

SELECT SUM(amount_inr) AS total_refund_amount 
FROM payments.upi_refunds 
WHERE requested_ts >= '2026-06-01' AND requested_ts < '2026-07-01';

SELECT sku, gtin, name, pack, case_kg 
FROM store.products 
WHERE name ILIKE '%atta%' OR pack ILIKE '%5 kg%' OR case_kg = 5;

SELECT COUNT(DISTINCT bill_id) AS distinct_bills 
FROM store.pos_lines 
WHERE bill_ts >= '2026-05-04' AND bill_ts < '2026-06-01';

SELECT COUNT(DISTINCT date(audit_ts)) AS empty_days 
FROM store.shelf_audits 
WHERE sku = 'ATTA-WW-5KG' AND status = 'empty';
